@Test
public void testApproveBasedOnUser() {
    AbstractPolicyBasedAuthorizer authorizer = Mockito.mock(AbstractPolicyBasedAuthorizer.class);
    final String userIdentifier = "userIdentifier1";
    final String userIdentity = "userIdentity1";
    final Set<AccessPolicy> policiesForResource = new HashSet<>();
    policiesForResource.add(new AccessPolicy.AccessPolicyBuilder().identifier("1").resource(TEST_RESOURCE).addUser(userIdentifier).addAction(RequestAction.READ).build());
    when(authorizer.getAccessPolicies(TEST_RESOURCE)).thenReturn(policiesForResource);
    final User user = new User.UserBuilder().identity(userIdentity).identifier(userIdentifier).build();
    when(authorizer.getUserByIdentity(userIdentity)).thenReturn(user);
    final AuthorizationRequest request = new AuthorizationRequest.Builder().identity(userIdentity).resource(TEST_RESOURCE).action(RequestAction.READ).accessAttempt(true).anonymous(false).build();
    assertEquals(AuthorizationResult.approved(), authorizer.authorize(request));
}

