    final RequestAction action = RequestAction.READ;
    final AccessPolicy policy = new AccessPolicy.AccessPolicyBuilder().identifier(identifier).resource(TEST_RESOURCE).addUser(user1).addUser(user2).addGroup(group1).addGroup(group2).addAction(action).build();
    assertEquals(identifier, policy.getIdentifier());
