            DataPacket packet;
            while (true) {
                packet = transaction.receive();
                if (packet == null) {
                    break;
                }
                final InputStream in = packet.getData();
                final long size = packet.getSize();
                final byte[] buff = new byte[(int) size];
                StreamUtils.fillBuffer(in, buff);
            }
            transaction.confirm();
            transaction.complete();
        }
    } finally {
        client.close();
    }
}

