@Test
public void testResize() throws IOException {
    final TestRunner runner = TestRunners.newTestRunner(new ResizeImage());
    runner.setProperty(ResizeImage.IMAGE_HEIGHT, "64");
    runner.setProperty(ResizeImage.IMAGE_WIDTH, "64");
    runner.setProperty(ResizeImage.SCALING_ALGORITHM, ResizeImage.RESIZE_SMOOTH);
    runner.enqueue(Paths.get("src/test/resources/simple.jpg"));
    runner.run();
    runner.assertAllFlowFilesTransferred(ResizeImage.REL_SUCCESS, 1);
    final MockFlowFile mff = runner.getFlowFilesForRelationship(ResizeImage.REL_SUCCESS).get(0);
    final byte[] data = mff.toByteArray();
    final BufferedImage img = ImageIO.read(new ByteArrayInputStream(data));
    assertEquals(64, img.getWidth());
    assertEquals(64, img.getHeight());
    final File out = new File("target/simple.jpg");
    ImageIO.write(img, "JPG", out);
}

@Test
public void validateFullConfigWithUserLib() throws Exception {
    TestRunner runner = TestRunners.newTestRunner(Mockito.mock(Processor.class));
    JMSConnectionFactoryProvider cfProvider = new JMSConnectionFactoryProvider();
    runner.addControllerService("cfProvider", cfProvider);
    runner.setProperty(cfProvider, JMSConnectionFactoryProvider.BROKER_URI, "myhost:1234");
    runner.setProperty(cfProvider, JMSConnectionFactoryProvider.CLIENT_LIB_DIR_PATH, // see README in 'test-lib' dir for more info
    new File("test-lib").getAbsolutePath());
    runner.setProperty(cfProvider, JMSConnectionFactoryProvider.CONNECTION_FACTORY_IMPL, "org.apache.nifi.jms.testcflib.TestConnectionFactory");
    runner.setProperty(cfProvider, "Foo", "foo");
    runner.setProperty(cfProvider, "Bar", "3");
    runner.enableControllerService(cfProvider);
    runner.assertValid(cfProvider);
    ConnectionFactory cf = cfProvider.getConnectionFactory();
    assertNotNull(cf);
    assertEquals("org.apache.nifi.jms.testcflib.TestConnectionFactory", cf.getClass().getName());
    assertEquals("myhost", this.get("getHost", cf));
    assertEquals(1234, ((Integer) this.get("getPort", cf)).intValue());
    assertEquals("foo", this.get("getFoo", cf));
    assertEquals(3, ((Integer) this.get("getBar", cf)).intValue());
}

